sp_widget.client_script:
api.controller = function($scope, $location) {

    var c = this;

    // -----------------------------------------
    // Form data
    // -----------------------------------------

    c.form = {
        claim_type: "",
        policy_number: "",
        incident_date: "",
        claim_amount: "",
        description: ""
    };

    c.submitting = false;
    c.successMessage = "";
    c.errorMessage = "";

    // -----------------------------------------
    // Submit Claim
    // -----------------------------------------

    c.submitClaim = function() {

        c.successMessage = "";
        c.errorMessage = "";

        // Check required fields
        if (!c.form.claim_type ||
            !c.form.policy_number ||
            !c.form.incident_date ||
            !c.form.claim_amount ||
            !c.form.description) {

            c.errorMessage =
                "Please fill in all required fields.";

            return;
        }

        c.submitting = true;

        // Send data to Server Script
        c.server.get({

            action: "submit_claim",

            claim: {
                claim_type: c.form.claim_type,
                policy_number: c.form.policy_number,
                incident_date: c.form.incident_date,
                claim_amount: c.form.claim_amount,
                description: c.form.description
            }

        }).then(function(response) {

            c.submitting = false;

            // -----------------------------------------
            // Claim successfully created
            // -----------------------------------------

            if (response.data.success === true) {

                c.successMessage =
                    "Claim " +
                    response.data.claim_number +
                    " has been submitted successfully.";

                // Clear form
                c.form = {
                    claim_type: "",
                    policy_number: "",
                    incident_date: "",
                    claim_amount: "",
                    description: ""
                };

                // -----------------------------------------
                // Go to OTP Verification
                // Pass exact Claim Sys ID
                // -----------------------------------------

                setTimeout(function() {

                    $scope.$apply(function() {

                        $location.search({

                            id: "otp_verification",

                            sys_id:
                                response.data.claim_sys_id

                        });

                    });

                }, 1000);

            } else {

                // -----------------------------------------
                // Server returned an error
                // -----------------------------------------

                c.errorMessage =
                    response.data.message ||
                    "Unable to submit the claim.";
            }

        }, function() {

            c.submitting = false;

            c.errorMessage =
                "An error occurred while submitting the claim.";

        });

    };

    // -----------------------------------------
    // Cancel / Go Home
    // -----------------------------------------

    c.goHome = function() {

        $location.search({

            id: "claim_home"

        });

    };

};

sp_widget.css:
.claim-submit-container {
    max-width: 1000px;
    margin: 40px auto;
    padding: 20px;
    font-family: Arial, sans-serif;
}

.claim-header {
    background: linear-gradient(135deg, #0d6efd, #1554a5);
    color: white;
    padding: 30px;
    border-radius: 12px 12px 0 0;
    display: flex;
    align-items: center;
    gap: 20px;
}

.claim-icon {
    width: 60px;
    height: 60px;
    background: rgba(255,255,255,0.18);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 30px;
}

.claim-header h1 {
    margin: 0 0 8px;
    font-size: 28px;
    font-weight: 600;
}

.claim-header p {
    margin: 0;
    opacity: 0.9;
}

.claim-form-card {
    background: white;
    padding: 35px;
    border: 1px solid #e1e5eb;
    border-radius: 0 0 12px 12px;
    box-shadow: 0 4px 15px rgba(0,0,0,0.08);
}

.section-title {
    margin-bottom: 25px;
}

.section-title h2 {
    margin: 0 0 6px;
    color: #183b67;
    font-size: 22px;
}

.section-title p {
    margin: 0;
    color: #6c757d;
}

.form-row {
    display: flex;
    gap: 25px;
    margin-bottom: 20px;
}

.form-group {
    flex: 1;
    margin-bottom: 20px;
}

.form-group label {
    display: block;
    margin-bottom: 8px;
    font-weight: 600;
    color: #34495e;
}

.form-group label span {
    color: #dc3545;
}

.form-control {
    width: 100%;
    min-height: 44px;
    padding: 10px 12px;
    border: 1px solid #ccd4dd;
    border-radius: 6px;
    font-size: 14px;
    box-sizing: border-box;
}

.form-control:focus {
    border-color: #0d6efd;
    outline: none;
    box-shadow: 0 0 0 2px rgba(13,110,253,0.12);
}

.description-box {
    resize: vertical;
}

.information-box {
    background: #eef6ff;
    border-left: 4px solid #0d6efd;
    padding: 15px;
    margin: 10px 0 25px;
    color: #36516c;
    border-radius: 4px;
}

.form-actions {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    margin-top: 25px;
}

.cancel-btn,
.submit-btn {
    padding: 12px 25px;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
    font-size: 14px;
}

.cancel-btn {
    background: white;
    border: 1px solid #adb5bd;
    color: #495057;
}

.submit-btn {
    background: #0d6efd;
    border: none;
    color: white;
}

.submit-btn:hover {
    background: #0b5ed7;
}

.submit-btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.message {
    padding: 14px;
    border-radius: 6px;
    margin-top: 15px;
}

.success-message {
    background: #e8f7ee;
    color: #18733c;
    border: 1px solid #b8e0c7;
}

.error-message {
    background: #fdecec;
    color: #a52834;
    border: 1px solid #f1b7bc;
}

@media (max-width: 700px) {

    .claim-submit-container {
        margin: 15px auto;
        padding: 10px;
    }

    .claim-header {
        padding: 22px;
    }

    .claim-header h1 {
        font-size: 22px;
    }

    .claim-form-card {
        padding: 22px;
    }

    .form-row {
        flex-direction: column;
        gap: 0;
    }

    .form-actions {
        flex-direction: column;
    }

    .cancel-btn,
    .submit-btn {
        width: 100%;
    }
}

sp_widget.script:
(function() {

    data.success = false;
    data.message = "";
    data.claim_number = "";
    data.claim_sys_id = "";

    if (!input || input.action != "submit_claim") {
        data.policies = [];
        var userEmail = gs.getUser().getEmail();
        var ph = new GlideRecordSecure('x_snc_insurance_0_policyholder');
        ph.addQuery('email', userEmail);
        ph.query();
        if (ph.next()) {
            var pol = new GlideRecordSecure('x_snc_insurance_0_policy');
            pol.addQuery('policyholder', ph.getUniqueValue());
            pol.query();
            while(pol.next()){
                data.policies.push({
                    sys_id: pol.getUniqueValue(),
                    number: pol.getValue('policy_number')
                });
            }
        }
        return;
    }

    try {

        var claimData = input.claim;

        if (!claimData) {
            data.message = "Claim information is missing.";
            return;
        }

        // Validate required fields
        if (!claimData.claim_type ||
            !claimData.policy_number ||
            !claimData.incident_date ||
            !claimData.claim_amount ||
            !claimData.description) {

            data.message = "Please fill in all required fields.";
            return;
        }

        // ------------------------------------------------
        // 1. Find Policy using Policy Number
        // ------------------------------------------------

        var policy = new GlideRecord("x_snc_insurance_0_policy");

        policy.addQuery(
            "policy_number",
            claimData.policy_number
        );

        policy.setLimit(1);
        policy.query();

        if (!policy.next()) {

            data.message =
                "Policy number " +
                claimData.policy_number +
                " was not found.";

            return;
        }

        // ------------------------------------------------
        // 2. Create Claim
        // ------------------------------------------------

        var claim = new GlideRecord("x_snc_insurance_0_claim");

        claim.initialize();

        // Claim Type
        claim.setValue(
            "claim_type",
            claimData.claim_type
        );

        // Policy Number reference
        claim.setValue(
            "policy_number",
            policy.getUniqueValue()
        );

        // Link to current user

        var userEmail = gs.getUser().getEmail();
        var ph = new GlideRecord("x_snc_insurance_0_policyholder");
        ph.addQuery("email", userEmail);
        ph.setLimit(1);
        ph.query();
        var phSysId = ph.next() ? ph.getUniqueValue() : "invalid";

        if (policy.getValue("policyholder") != phSysId) {
            data.message = "You are not authorized to submit a claim for this policy.";
            return;
        }

        claim.setValue(
            "policyholder",
            phSysId
        );


        // Incident Date
        claim.setValue(
            "incident_date",
            claimData.incident_date
        );

        // Claim Amount
        claim.setValue(
            "claim_amount",
            claimData.claim_amount
        );

        // Description
        claim.setValue(
            "description",
            claimData.description
        );

        // ------------------------------------------------
        // 3. Insert Claim
        // ------------------------------------------------

        var newSysId = claim.insert();

        if (!newSysId) {

            data.message =
                "Claim could not be created.";

            return;
        }

        // ------------------------------------------------
        // 4. Return Claim information to Client
        // ------------------------------------------------

        data.success = true;

        data.claim_sys_id =
            claim.getUniqueValue();

        data.claim_number =
            claim.getValue("claim_number");

        data.message =
            "Claim submitted successfully.";

    } catch (e) {

        data.success = false;

        data.message =
            "Error while submitting claim: " +
            e.message;
    }

})();
